#!/bin/bash
$ErrorActionPreference = "SilentlyContinue"; $pinfo = New-Object System.Diagnostics.ProcessStartInfo; $pinfo.FileName = "C:\Program Files\WSL\wsl.exe"; $pinfo.Arguments = "-d Ubuntu -- bash -c ""apt-get update -qq 2>&1 | tail -3 && apt-get install -y -qq curl ca-certificates 2>&1 | tail -5"""; $pinfo.RedirectStandardOutput = $true; $pinfo.RedirectStandardError = $true; $pinfo.UseShellExecute = $false; $pinfo.CreateNoWindow = $true; $pinfo.StandardOutputEncoding = [System.Text.Encoding]::UTF8; $pinfo.StandardErrorEncoding = [System.Text.Encoding]::Default; $p = New-Object System.Diagnostics.Process; $p.StartInfo = $pinfo; $p.Start() | Out-Null; $stdout = $p.StandardOutput.ReadToEnd(); $stderr = $p.StandardError.ReadToEnd(); $p.WaitForExit(); Write-Host "Exit: $($p.ExitCode)"; Write-Host $stdout; if ($stderr) { Write-Host "STDERR: $stderr" }
echo "\n[flowcraft:exit:$?]"